<script setup lang="ts">import{reactive,ref,onMounted,onUnmounted}from'vue';import{api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import StatusBadge from'../components/StatusBadge.vue';import{Search,Route,ShieldCheck,Database,Globe2}from'lucide-vue-next';const form=reactive({access_key:'',document_type:'nfe',legal_entity_id:''});const entities=ref<any[]>([]),job=ref<any|null>(null),error=ref(''),loading=ref(false);async function load(){entities.value=(await api.get('/legal-entities')).data}async function submit(){loading.value=true;error.value='';try{job.value=(await api.post('/retrieval-jobs',{...form,legal_entity_id:form.legal_entity_id||null})).data;poll()}catch(e){error.value=errorMessage(e);loading.value=false}}async function poll(){if(!job.value)return;const timer=setInterval(async()=>{job.value=(await api.get(`/retrieval-jobs/${job.value.id}`)).data;if(['completed','not_found','failed','human_action_required'].includes(job.value.status)){clearInterval(timer);loading.value=false}},1500)}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))
</script><template><PageHeader title="Consultar documento" subtitle="O orquestrador percorre as fontes habilitadas até localizar um XML completo e válido"/><div class="query-layout"><section class="panel query-card"><div class="query-icon"><Search/></div><h2>Consulta por chave ou identificador</h2><p>Antes de consultar provedores externos, o sistema verifica o próprio repositório.</p><form class="form-grid" @submit.prevent="submit"><label class="span-2">Chave de acesso<input v-model="form.access_key" placeholder="Informe a chave de 44 dígitos ou identificador NFS-e" required/></label><label>Tipo<select v-model="form.document_type"><option value="nfe">NF-e</option><option value="nfce">NFC-e</option><option value="cte">CT-e</option><option value="mdfe">MDF-e</option><option value="nfse">NFS-e</option></select></label><label>Empresa<select v-model="form.legal_entity_id"><option value="">Não especificada</option><option v-for="e in entities" :value="e.id">{{e.legal_name}}</option></select></label><div v-if="error" class="alert danger span-2">{{error}}</div><button class="btn primary span-2" :disabled="loading">{{loading?'Consultando fontes...':'Iniciar consulta'}}</button></form></section><section class="panel route-preview"><h3>Fluxo inteligente</h3><div class="route-step"><Database/><div><strong>1. Repositório próprio</strong><span>Resposta imediata e sem custo externo.</span></div></div><i></i><div class="route-step"><Route/><div><strong>2. Plugins automáticos</strong><span>Executados conforme prioridade e saúde.</span></div></div><i></i><div class="route-step"><ShieldCheck/><div><strong>3. Validação fiscal</strong><span>XML, protocolo, hash e deduplicação.</span></div></div><i></i><div class="route-step"><Globe2/><div><strong>4. Fonte assistida</strong><span>Somente quando uma pessoa for necessária.</span></div></div></section></div><section v-if="job" class="panel result-panel"><div class="panel-title"><div><h3>Operação {{job.id}}</h3><p>{{job.access_key}}</p></div><StatusBadge :status="job.status"/></div><div class="progress large"><i :style="{width:`${job.progress}%`}"></i></div><div class="attempt-grid"><article v-for="attempt in job.attempts" :key="attempt.at"><strong>{{attempt.installation}}</strong><StatusBadge :status="attempt.status"/><small>{{attempt.message||'Processado'}}</small></article></div><div v-if="job.human_action" class="alert warning">Ação humana necessária: {{job.human_action.instructions}}</div><RouterLink v-if="job.result_document_id" class="btn primary" to="/documents">Abrir documento</RouterLink></section></template>
